import SwiftUI

/// A template image from `Assets.xcassets/UI` (generated by
/// scripts/mobile/generate-ios-ui-assets.mjs from the mockup's SVGs).
struct AssetIcon: View {
    let name: String
    let size: CGFloat
    var height: CGFloat?
    var color: Color?
    init(_ name: String, size: CGFloat, height: CGFloat? = nil, color: Color? = nil) {
        self.name = name; self.size = size; self.height = height; self.color = color
    }
    var body: some View {
        Image(name)
            .renderingMode(.template)
            .resizable()
            .scaledToFit()
            .foregroundStyle(color ?? .primary)
            .frame(width: size, height: height ?? size)
            .accessibilityHidden(true)
    }
}

/// Lucide icon by name and stroke width, as the mockup uses it (`Lucide-<name>-<stroke>`).
struct Lucide: View {
    let name: String
    let size: CGFloat
    var stroke: String = "2"
    var color: Color?
    var body: some View { AssetIcon("Lucide-\(name)-\(stroke)", size: size, color: color) }
}

enum PCBadgeName: String { case wifi, ban, send, receive, mute, warning }

/// PC device icon (mockup `DevIcon`): a 16-unit glyph with an optional corner badge whose
/// knock-out ring is cut out of the glyph, so it works on any background.
/// List variant: box = glyph × 18/16, badge = glyph × 10/16. Volume variant: box = glyph,
/// badge = glyph × 12/22 (PC volume rows).
struct PCIcon: View {
    @Environment(\.oink) private var oink
    let glyph: String
    var badge: PCBadgeName?
    var size: CGFloat
    var color: Color
    var volume = false
    /// The `receive` badge is the accent colour unless the icon tone is good (PC rule).
    var toneIsGood = false

    private var box: CGFloat { volume ? size : size * 18 / 16 }
    private var badgeSize: CGFloat { volume ? size * 12 / 22 : size * 10 / 16 }

    var body: some View {
        ZStack(alignment: .topLeading) {
            AssetIcon("PCGlyph-\(glyph)", size: size, color: color)
                .frame(width: box, height: box, alignment: .topLeading)
                .mask {
                    KnockOut(hole: badge == nil ? nil : CGRect(x: box - badgeSize, y: box - badgeSize, width: badgeSize, height: badgeSize),
                             radius: badgeSize / 2)
                        .fill(style: FillStyle(eoFill: true))
                }
            if let badge {
                Group {
                    if badge == .warning {
                        Image("PCBadge-warning").resizable()
                    } else {
                        AssetIcon("PCBadge-\(badge.rawValue)", size: badgeSize,
                                  color: badge == .receive && !toneIsGood ? oink.accent : color)
                    }
                }
                .frame(width: badgeSize, height: badgeSize)
                .offset(x: box - badgeSize, y: box - badgeSize)
            }
        }
        .frame(width: box, height: box, alignment: .topLeading)
        .accessibilityHidden(true)
    }
}

/// Device platform from the card / pairing data.
enum DevicePlatform: String {
    case mac, windows, linux, other, iphone, ipad, android

    init(os: String, name: String = "") {
        switch os.lowercased() {
        case "macos", "mac", "darwin": self = .mac
        case "windows", "win": self = .windows
        case "linux": self = .linux
        case "android": self = .android
        case "ipados", "ipad": self = .ipad
        case "ios", "iphone":
            self = name.lowercased().contains("ipad") ? .ipad : .iphone
        default: self = .other
        }
    }
    var isMobile: Bool { self == .iphone || self == .ipad || self == .android }
    var isComputer: Bool { !isMobile }
}

/// Platform logo in the mockup's 32 × 36 slot (`.m-platform`), scaled by `scale`.
/// mac 28, Windows 24, other 24, Android head 30 × 17.5, iPhone / iPad = Apple logo with
/// the device corner mark (14 × 18 / rotated 17 × 20) cut into it.
struct PlatformLogo: View {
    @Environment(\.oink) private var oink
    let platform: DevicePlatform
    var scale: CGFloat = 1
    /// Overrides the platform colour (offline, disabled proxy).
    var color: Color?
    /// Android privileged mode is on and running: a gold crown above the head
    /// (native-rewrite.md「Android 特权模式徽标」). Never set for offline devices.
    var privileged = false

    private var crowned: Bool { platform == .android && privileged }

    var body: some View {
        let s = scale
        ZStack {
            switch platform {
            case .windows:
                AssetIcon("PCOS-win", size: 24 * s, color: color ?? oink.osWindows)
            case .mac:
                AssetIcon("PCOS-mac", size: 28 * s, color: color ?? oink.ink)
            case .linux, .other:
                AssetIcon("PCOS-other", size: 24 * s, color: color ?? oink.ink)
            case .android:
                AssetIcon("OSAndroid-head", size: 30 * s, height: 17.5 * s, color: color ?? oink.osAndroid)
                    .mask {
                        // Eyes are cut out of the head. A luminanceToAlpha mask (white keeps,
                        // black removes) left the eyes filled on the iOS 27 simulator, so the
                        // eyes erase an opaque layer instead: destinationOut inside the mask's
                        // own compositing group only changes the mask's alpha, so the holes
                        // still show whatever surface is behind the badge.
                        ZStack {
                            Rectangle()
                            AssetIcon("OSAndroid-eyes", size: 30 * s, height: 17.5 * s, color: .black)
                                .blendMode(.destinationOut)
                        }
                        .compositingGroup()
                    }
                if crowned {
                    // The crown assets use the head's units with 24 extra above and below
                    // (30 × 27.02), so centred in the slot the crown sits on the unmoved head.
                    // Two layers: path + round stroke in the edge colour is the whole
                    // footprint; the bare path in the crown colour on top leaves a 0.5 pt rim.
                    AssetIcon("OSAndroid-crown-edge", size: 30 * s, height: 30 * 136 / 151 * s, color: oink.crownEdge)
                    AssetIcon("OSAndroid-crown", size: 30 * s, height: 30 * 136 / 151 * s, color: oink.crown)
                }
            case .iphone, .ipad:
                appleDevice(s)
            }
        }
        .frame(width: 32 * s, height: 36 * s)
        .modifier(PlatformLogoAccessibility(label: crowned ? AppText.pick("Android，特权模式已开启", "Android, privileged mode on") : nil))
    }

    /// `.m-apple-device` (mockup 2026-11-08): the corner box is 12 × 16 (iPhone, right 2,
    /// bottom 2 → x 18–30, y 18–34) or 13 × 16 rotated 90° (iPad, right 3.5, bottom 1.5 before
    /// rotation). Its background plus a 1.5 ring (radius 2.5 + 1.5) is the cut-out colour, so
    /// here that whole rounded region is cut out of the Apple logo by a mask (no seam).
    private func appleDevice(_ s: CGFloat) -> some View {
        let ipad = platform == .ipad
        let w: CGFloat = ipad ? 13 : 12, h: CGFloat = 16
        let right: CGFloat = ipad ? 3.5 : 2, bottom: CGFloat = ipad ? 1.5 : 2
        let cx = 32 - right - w / 2, cy = 36 - bottom - h / 2
        // Visual box after the iPad's 90° rotation.
        let vw = ipad ? h : w, vh = ipad ? w : h
        let x = cx - vw / 2, y = cy - vh / 2
        let tint = color ?? oink.ink
        return ZStack(alignment: .topLeading) {
            AssetIcon("PCOS-mac", size: 28 * s, color: tint).offset(x: 2 * s, y: 4 * s)
                .frame(width: 32 * s, height: 36 * s, alignment: .topLeading)
                .mask {
                    KnockOut(hole: CGRect(x: (x - 1.5) * s, y: (y - 1.5) * s, width: (vw + 3) * s, height: (vh + 3) * s), radius: 4 * s)
                        .fill(style: FillStyle(eoFill: true))
                }
            AssetIcon(ipad ? "OSCorner-ipad" : "OSCorner-iphone", size: w * s, height: h * s, color: tint)
                .rotationEffect(.degrees(ipad ? 90 : 0))
                .frame(width: vw * s, height: vh * s)
                .offset(x: x * s, y: y * s)
        }
        .frame(width: 32 * s, height: 36 * s, alignment: .topLeading)
    }
}

/// Platform logos are decoration next to the device name, except the crowned Android
/// head, which reads as「Android，特权模式已开启」.
private struct PlatformLogoAccessibility: ViewModifier {
    let label: String?
    @ViewBuilder func body(content: Content) -> some View {
        if let label {
            content.accessibilityElement(children: .ignore).accessibilityLabel(label).accessibilityAddTraits(.isImage)
        } else {
            content.accessibilityHidden(true)
        }
    }
}

/// PC latency bars (20 × 18.6 in the list): three-bar track, lit bars by latency.
struct SignalBars: View {
    @Environment(\.oink) private var oink
    let latency: Int?
    var width: CGFloat = 20
    var body: some View {
        let level = latency.map { $0 < 20 ? 3 : $0 <= 50 ? 2 : 1 } ?? 0
        let tone = level == 3 ? oink.good : level == 2 ? oink.warning : oink.bad
        let h = width * 13 / 14
        ZStack {
            AssetIcon("PCSignal-3", size: width, height: h, color: oink.track)
            if level > 0 { AssetIcon("PCSignal-\(level)", size: width, height: h, color: tone) }
        }
        .accessibilityHidden(true)
    }
}

/// Mockup state of a device capability (PC `indicators()`).
struct CapabilityIndicator: Hashable {
    var glyph: String
    var tone: IconTone
    var badge: PCBadgeName?
    var label: String
}

/// Volume → number of speaker arcs (PC `volumeWaves`, level on the 0–200 scale).
func volumeWaves(_ v: Int) -> Int { v <= 0 ? 0 : v <= 33 ? 1 : v <= 66 ? 2 : v <= 100 ? 3 : 4 }

/// A mask that keeps everything except one rounded hole (badge knock-outs, the iPhone/iPad
/// corner). Uses even-odd filling rather than blend modes, so the cut-out shows whatever is
/// behind the icon on every surface, including Liquid Glass.
struct KnockOut: Shape {
    var hole: CGRect?
    var radius: CGFloat
    func path(in rect: CGRect) -> Path {
        var path = Path(rect.insetBy(dx: -40, dy: -40))
        if let hole { path.addRoundedRect(in: hole, cornerSize: CGSize(width: radius, height: radius), style: .circular) }
        return path
    }
}
